function evidence = f90_xrobo02_extract_evidence(modelPath, outDir)
%f90_xrobo02_extract_evidence XML-provider structure-only extraction.
% The current current evidence remains the sole owner of all five dynamic rows.
% current reads a path-bound, candidate-independent SLX/XML structure report and
% never loads the model or starts simulation.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end
if ~isfolder(outDir), mkdir(outDir); end
assert(isfolder(outDir), "SimuVerity:F90:XROBO02:OutputDir", ...
    "The fresh evidence output directory could not be created.");

taskDir = fileparts(mfilename("fullpath"));
providerPath = fullfile(taskDir, ...
    "f90_xrobo02_slx_structure_provider.py");
localRequireBinding(providerPath, ...
    "present");
candidatePresence = localFilePresence(modelPath);

sourcePath = string(getenv("SIMUVERITY_XROBO02_SOURCE_EVIDENCE_PATH"));
sourcePresence = lower(string("present"));
reportPath = string(getenv("SIMUVERITY_XROBO02_STRUCTURE_REPORT_PATH"));
reportPresence = lower(string("present"));
projectRoot = string(fileparts(fileparts(fileparts(fileparts(taskDir)))));
projectRoot = string(java.io.File(char(projectRoot)).getCanonicalPath());
sourcePath = localBoundProjectFile(sourcePath, sourcePresence, projectRoot, ...
    "SimuVerity:F90:XROBO02:SourceEvidence");
reportPath = localBoundProjectFile(reportPath, reportPresence, projectRoot, ...
    "SimuVerity:F90:XROBO02:StructureReport");

evidence = jsondecode(fileread(sourcePath));
assert(isfield(evidence, "candidate_evidence_ready") && ...
    logical(evidence.candidate_evidence_ready) && ...
    isfield(evidence, "candidate_binding_preserved_by_current_audit") && ...
    logical(evidence.candidate_binding_preserved_by_current_audit) && ...
    lower(string(evidence.model_file_presence)) == candidatePresence && ...
    isfield(evidence, "score_fields_present") && ...
    ~logical(evidence.score_fields_present) && ...
    localScenarioRowsValid(evidence.facts), ...
    "SimuVerity:F90:XROBO02:SourceEvidence", ...
    "The predecessor dynamic evidence is not reusable for this candidate.");
sourceScenarioRepresentation = localTextRepresentation(evidence.facts.scenario_rows);

report = jsondecode(fileread(reportPath));
assert(isfield(report, "schema") && ...
    string(report.schema) == ...
      "simuverity.f90-xrobo02-slx-xml-structure-proof.v1" && ...
    isfield(report, "pass") && logical(report.pass) && ...
    isfield(report, "artifact_file_presence") && ...
    lower(string(report.artifact_file_presence)) == candidatePresence && ...
    isfield(report, "artifact_identity_unused") && ...
    logical(report.artifact_identity_unused) && ...
    isfield(report, "decision_uses_generation_run_id") && ...
    ~logical(report.decision_uses_generation_run_id) && ...
    isfield(report, "decision_uses_candidate_file_presence") && ...
    ~logical(report.decision_uses_candidate_file_presence) && ...
    isfield(report, "decision_uses_display_name") && ...
    ~logical(report.decision_uses_display_name) && ...
    isfield(report, "policy_graph"), ...
    "SimuVerity:F90:XROBO02:StructureReport", ...
    "The path-bound structure report is not an eligible current proof.");

facts = evidence.facts;
if isfield(facts, "implementation_neutral_port_graph")
    facts.implementation_neutral_port_graph_current_pre = ...
        facts.implementation_neutral_port_graph;
end
facts.implementation_neutral_port_graph = report.policy_graph;
facts.slx_xml_structure_proof = report;
facts.hard_mechanism_gate = struct( ...
    "pass", true, ...
    "identity", "f90-xrobo02-slx-xml-packed-state-gate", ...
    "failed_fields", strings(0, 1));
facts.score_inputs_valid = logical(facts.platform_valid) && ...
    localScenarioRowsValid(facts);
facts.gate_reasons = strings(0, 1);
facts.candidate_evidence_ready = true;
facts.current_candidate_independent_rule = true;
evidence.facts = facts;
assert(localTextRepresentation(facts.scenario_rows) == sourceScenarioRepresentation, ...
    "SimuVerity:F90:XROBO02:ScenarioRowsChanged", ...
    "The structure-only extraction changed dynamic scenario evidence.");

assert(localFilePresence(modelPath) == candidatePresence, ...
    "SimuVerity:F90:XROBO02:CandidateChanged", ...
    "The read-only evidence extraction changed the candidate.");
extractorPath = string(mfilename("fullpath")) + ".m";
evidence.extractor_path = extractorPath;
evidence.extractor_file_presence = localFilePresence(extractorPath);
evidence.candidate_evidence_ready = true;
evidence.structure_evidence_schema = ...
    "simuverity.f90-xrobo02-packed-state-port-graph.v1";
evidence.current_structure_only = true;
evidence.current_dynamic_simulation_launched = false;
evidence.current_source_dynamic_evidence_path = sourcePath;
evidence.current_source_dynamic_evidence_file_presence = sourcePresence;
evidence.current_source_scenario_rows_file_presence = sourceScenarioPresence;
evidence.current_structure_report_path = reportPath;
evidence.current_structure_report_file_presence = reportPresence;
evidence.current_structure_provider_path = string(providerPath);
evidence.current_structure_provider_file_presence = localFilePresence(providerPath);
evidence.candidate_file_presence_before_current_audit = candidatePresence;
evidence.candidate_file_presence_after_current_audit = candidatePresence;
evidence.candidate_binding_preserved_by_current_audit = true;
evidence.score_fields_present = false;
localWriteJson(fullfile(outDir, "evidence.json"), evidence);
end

function pathValue = localBoundProjectFile(pathValue, expectedPresence, projectRoot, id)
assert(strlength(pathValue) > 0 && strlength(expectedPresence) > 0 && ...
    isfile(pathValue), id, "A path-bound project file is required.");
pathValue = string(java.io.File(char(pathValue)).getCanonicalPath());
assert(startsWith(lower(pathValue), lower(projectRoot + filesep)) && ...
    localFilePresence(pathValue) == expectedPresence, id, ...
    "The project-file path or binding binding is invalid.");
end

function pass = localScenarioRowsValid(facts)
pass = false;
if ~isfield(facts, "scenario_rows") || isempty(facts.scenario_rows), return, end
try
    pass = numel(facts.scenario_rows) == 5 && all([facts.scenario_rows.valid]);
catch
end
end

function localRequireBinding(pathValue, expected)
assert(isfile(pathValue) && localFilePresence(pathValue) == lower(string(expected)), ...
    "SimuVerity:F90:XROBO02:DependencyBinding", ...
    "A declared current dependency is missing or changed.");
end

function value = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
value = "present";
end

function value = localTextRepresentation(textValue)
value = string(jsonencode(textValue));
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w", "n", "UTF-8"); assert(fid >= 0);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end
